import{_ as a,o as s,c as i,a5 as t}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"国际化与无障碍","description":"","frontmatter":{"title":"国际化与无障碍","docId":"developer.i18n-accessibility","translationKey":"developer.i18n-accessibility","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2c74fcefd1d28353b1135c547b2e3e6ae852af8b683350011732d10c364f9323","translationRevision":"4740b64ac0a82bd91ef2886fa9475030342be22ba5afc43366d07fcf3a46ba38","order":120},"headers":[],"relativePath":"zh/developer/i18n-accessibility.md","filePath":"zh/developer/i18n-accessibility.md","lastUpdated":1794611623000}'),o={name:"zh/developer/i18n-accessibility.md"};function l(n,e,c,d,r,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="internationalization-and-accessibility" tabindex="-1">国际化与无障碍 <a class="header-anchor" href="#internationalization-and-accessibility" aria-label="Permalink to &quot;国际化与无障碍 {#internationalization-and-accessibility}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>添加在受支持语言中仍清晰可懂，并可通过键盘、触控和辅助技术使用的页面。先阅读<a href="./frontend.html">前端分层</a>，并使用现有共享 UI。运行时应用语言与公开文档版本是两个独立系统。</p><h2 id="add-localized-content" tabindex="-1">添加本地化内容 <a class="header-anchor" href="#add-localized-content" aria-label="Permalink to &quot;添加本地化内容 {#add-localized-content}&quot;">​</a></h2><p>应用语言目录位于 <code>src/web/shared/i18n/</code>。英语是类型化回退语言；其他所有受支持目录均按需加载。<code>activateLocale</code> 加载选定消息并更新 <code>document.documentElement.lang</code>。通过现有语言 store 保存偏好，不要另写本地存储键。</p><ol><li>在英语目录及对应的受支持目录/模块中添加语义化消息键。</li><li>保持 API ID、事件路径和存储资源标识符稳定；翻译其可见标签。</li><li>变量文本使用插值，显示值使用共享国际化辅助函数。</li><li>插件描述符使用现有 <code>{default,i18key}</code> 本地化文本契约及宿主合并目录。绝不要将翻译或插件提供的字符串作为 HTML 渲染。</li></ol><h2 id="preserve-control-semantics" tabindex="-1">保留控件语义 <a class="header-anchor" href="#preserve-control-semantics" aria-label="Permalink to &quot;保留控件语义 {#preserve-control-semantics}&quot;">​</a></h2><p>优先使用 <code>BaseTextField</code>、<code>BaseFormRow</code>、<code>BaseDialog</code>、标签页和状态组件。占位文本不能替代无障碍标签。图标按钮需要本地化名称。验证必须指出字段并公开无效状态，不能只用颜色表达失败。保留对话框焦点返回、Escape 行为、键盘选择及可见焦点轮廓。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalogs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BaseDialog</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span></code></pre></div><p>手动审查时，用 Tab 遍历完整流程，打开/关闭对话框，在对话框打开时切换语言，并在窄屏下重复。悬停时显示的状态操作，也必须在键盘聚焦时显示，并可通过触控使用。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>目录类型和对等检查会捕获缺失键；共享控件提供已实现的键盘及 ARIA 行为。这不等于每个组合页面都获得全面无障碍认证。即使存在译文字符串，排名与竞赛仍保持隐藏。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>出现未翻译文本时，先检查延迟目录加载及精确键名，再考虑在组件中添加英语回退。焦点消失时，检查接收转发属性的控件及对话框返回目标。<a href="https://github.com/nglmercer/TikTools-app/blob/remake/src/web/shared/i18n/i18n.ts" target="_blank" rel="noreferrer">i18n 实现</a>及组件测试定义当前行为；<a href="./components/">组件指南</a>说明共享入口。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>语言选择顺序为已保存的 <code>tiktok-live-locale</code> → <code>navigator.languages</code> → 英语。<code>normalizeLocale</code> 处理地区标签及 <code>jp</code> → <code>ja</code>。界面代码/格式地区为 <code>en/en-US</code>、<code>es/es-ES</code>、<code>pt/pt-BR</code>、<code>fr/fr-FR</code>、<code>zh/zh-CN</code>、<code>ja/ja-JP</code>，使用 <code>intl.ts</code> 的 formatCount/formatDate。<code>activateLocale</code> 加载消息并设置文档 lang；<code>useLocaleStore().setLocale</code> 还持久保存并尽力暂存偏好。设置控件应使用 store。英语为回退，zh/ja 另加载宿主消息模块。新增语言需更新 supported-locales、懒加载、目录/宿主消息、格式地区映射、偏好测试、键/占位符/复数及编译测试，以及 docs/站点语言路由。API ID 和参数名不翻译。</p><p>使用间距、字体、控件、焦点及层级 tokens。任意粗指针或宽度小于 700px 时，控件升至 44px；导航在 900px 下变化，表单行在 600px 下变化，彼此独立。减少动画偏好将时长归零。也要测试宽屏粗指针。应用整体为深色，浅色覆盖仅用于 JSON，不是全局浅色主题。</p><p>键盘契约：标签用方向键/Home/End 自动选择；select 用方向键/Home/End/Enter，Escape 取消；菜单关闭后返回触发器。对话框使用原生 showModal 焦点限制，但 <code>closable=false</code> 禁止 Escape，关闭会卸载内容。草稿归所有者，并核对初始/返回焦点。图标按钮需要 <code>label</code>，<code>hint</code>/tooltip 只是解释。tooltip 在悬停/聚焦 500ms 后出现、Escape 关闭并位于对话框顶层。真实键盘/辅助流程仍需人工检查，单元测试不能认证整屏。</p>`,18)])])}const b=a(o,[["render",l]]);export{k as __pageData,b as default};
